import unittest
from candidate import string_xor

class TestStringXOR(unittest.TestCase):
    def test_normal_case_identical_bits(self):
        self.assertEqual(string_xor('000', '000'), '000')

    def test_normal_case_different_bits(self):
        self.assertEqual(string_xor('0101', '1010'), '1111')

    def test_normal_case_mixed_lengths(self):
        self.assertEqual(string_xor('101', '10'), '11')

    def test_empty_string_first(self):
        self.assertEqual(string_xor('', '1010'), '')

    def test_empty_string_second(self):
        self.assertEqual(string_xor('1010', ''), '')

    def test_both_empty_strings(self):
        self.assertEqual(string_xor('', ''), '')

    def test_all_zeros(self):
        self.assertEqual(string_xor('0000', '0000'), '0000')

    def test_all_ones(self):
        self.assertEqual(string_xor('1111', '1111'), '0000')

    def test_uneven_lengths(self):
        self.assertEqual(string_xor('10101', '101'), '110')

    def test_single_bit(self):
        self.assertEqual(string_xor('1', '0'), '1')
        self.assertEqual(string_xor('0', '1'), '1')
        self.assertEqual(string_xor('1', '1'), '0')

    def test_type_error_invalid_characters(self):
        with self.assertRaises(TypeError):
            string_xor('012', '101')

    def test_type_error_non_string(self):
        with self.assertRaises(TypeError):
            string_xor([], '101')

    def test_type_error_mixed_types(self):
        with self.assertRaises(TypeError):
            string_xor('101', 101)

    def test_case_sensitivity(self):
        self.assertEqual(string_xor('010', '110'), '100')
        self.assertEqual(string_xor('010', '110'.upper()), '100')
